use darling::{FromDeriveInput, FromVariant, ast::Fields};
use proc_macro2::{Span, TokenStream};
use quote::quote;
use syn::Ident;

/// Name of the module generated by the [`Message`] macro which contains the
/// message enum variant type aliases
pub const MESSAGE_META_TYPES_IDENT: &str = "__message_meta_types";

// The [`darling::FromVariant`] macro seems to have needless continues
#[allow(clippy::needless_continue)]
#[derive(FromVariant)]
struct MessageVariant {
    ident: Ident,
    fields: Fields<syn::Field>,
}

#[derive(FromDeriveInput)]
#[darling(supports(enum_any))]
pub struct Message {
    data: darling::ast::Data<MessageVariant, ()>,
}

pub fn handle(message: Message) -> TokenStream {
    let variants = message.data.take_enum().unwrap_or_default();

    let meta_types_mod = Ident::new(MESSAGE_META_TYPES_IDENT, Span::call_site());
    let meta_types = meta_types(&variants);

    quote! {
        /// generated by [`data_macros::Message`] macro
        pub mod #meta_types_mod {
            #[allow(clippy::wildcard_imports)]
            use super::*;

            #meta_types
        }
    }
}

/// Generate the type aliases for all message variants
///
/// Note that for non-newtype variants the type aliases are created like this
/// - If the variant is a struct type, then instead of a type alias a new struct with
///   all fields of the variant is created \
///   **Important**: All fields of the struct need to implement [`bincode::Encode`] and [`bincode::Decode`]
///   as the new struct derives those traits
/// - If the variant is a tuple type (with more than one type), then instead of a type alias
///   a new tuple with all fields of the variant is created \
///   **Important**: All fields of the tuple need to implement [`bincode::Encode`] and [`bincode::Decode`]
///   as the tuple type won't be encodable/decodable otherwise
fn meta_types(variants: &[MessageVariant]) -> TokenStream {
    let type_defs = variants
        .iter()
        .map(|variant| {
            let (types, type_idents) = variant
                .fields
                .iter()
                .map(|field| (&field.ty, &field.ident))
                .collect::<(Vec<_>, Vec<_>)>();

            let ident = &variant.ident;

            if variant.fields.is_struct() {
                // if the variant is a struct type, we create a new struct with the same fields
                // instead of a type alias
                quote! {
                    #[derive(bincode::Encode, bincode::Decode)]
                    pub struct #ident {
                        #(pub #type_idents: #types),*
                    }
                }
            } else if variant.fields.is_unit() {
                quote! { pub type #ident = (); }
            } else if variant.fields.is_newtype()
                && let Some(field_type) = types.first()
            {
                quote! { pub type #ident = #field_type; }
            } else {
                // if the variant is a tuple type with more than one type, we create a new
                // tuple with the same fields instead of a type alias
                quote! { pub type #ident = (#(#types),*); }
            }
        })
        .collect::<Vec<_>>();

    quote! {
        #(#type_defs)*
    }
}
